CREATE OR REPLACE FUNCTION public.home_sync_fixed_month_items(p_month_key text, p_currency text DEFAULT 'JPY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_updated_count integer:=0;
begin
  if public.home_fixed_scope_has_external_projection(p_month_key,p_currency) then return jsonb_build_object('ok',false,'code','HOME_PROJECTION_FIXED_ITEM_SYNC_FORBIDDEN','message','范围内包含School信用卡projection固定项，不能使用普通月份/模板同步writer。'); end if;
  if public.home_fixed_scope_has_card_statement(p_month_key,p_currency) then return jsonb_build_object('ok',false,'code','HOME_CARD_STATEMENT_ITEM_SYNC_FORBIDDEN','message','范围内包含信用卡statement关联固定项，不能使用普通月份/模板同步writer。'); end if;
  with month_context as(select extract(year from month_start)::int year_no,extract(month from month_start)::int month_no,extract(day from(month_start+interval '1 month - 1 day'))::int days_in_month from(select to_date(p_month_key||'-01','YYYY-MM-DD') month_start)d),
  updated_items as(update public.home_fixed_month_items i set direction=t.direction,name=t.name,amount=t.default_amount,account_id=t.default_account_id,payment_group=t.payment_group,due_date=case when t.due_day is null then null else make_date(c.year_no,c.month_no,least(t.due_day,c.days_in_month)) end,term_no=case when t.fixed_type='short_term' and t.start_month is not null and t.total_terms is not null then((substring(p_month_key,1,4)::int-substring(t.start_month,1,4)::int)*12+(substring(p_month_key,6,2)::int-substring(t.start_month,6,2)::int)+1) else null end,total_terms=case when t.fixed_type='short_term' then t.total_terms else null end from public.home_fixed_templates t cross join month_context c where i.template_id=t.id and i.user_id=auth.uid() and t.user_id=auth.uid() and i.month_key=p_month_key and i.currency=p_currency and t.currency=p_currency returning i.id)
  select count(*) into v_updated_count from updated_items;
  return jsonb_build_object('updated_count',v_updated_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.home_check_fixed_paid_balance(p_month_key text, p_currency text DEFAULT 'JPY'::text, p_target_item_id uuid DEFAULT NULL::uuid, p_target_status text DEFAULT NULL::text, p_bulk_direction text DEFAULT NULL::text, p_bulk_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_actual_income numeric := 0;
  v_actual_expense numeric := 0;
begin
  if p_target_status is not null and p_target_status not in ('unpaid', 'paid', 'settled') then
    return jsonb_build_object('ok', false, 'message', '固定项状态无效。');
  end if;

  if p_bulk_status is not null and p_bulk_status not in ('unpaid', 'paid', 'settled') then
    return jsonb_build_object('ok', false, 'message', '固定项状态无效。');
  end if;

  if p_bulk_direction is not null and p_bulk_direction not in ('income', 'expense') then
    return jsonb_build_object('ok', false, 'message', '固定项收支方向无效。');
  end if;

  with month_items as (
    select
      i.*,
      case
        when i.linked_jpy_transaction_id is not null then 'paid'
        when p_target_item_id is not null and i.id = p_target_item_id then p_target_status
        when p_bulk_direction is not null and i.direction = p_bulk_direction then p_bulk_status
        else i.status
      end as next_status
    from home_fixed_month_items i
    where i.user_id = auth.uid()
      and i.month_key = p_month_key
      and i.currency = p_currency
  ),
  paid_expense_groups as (
    select
      coalesce(payment_group, '未分组') as payment_group,
      home_round_up_1000(coalesce(sum(amount), 0)) as paid_amount
    from month_items
    where direction = 'expense'
      and next_status in ('paid', 'settled')
    group by coalesce(payment_group, '未分组')
  )
  select
    coalesce(sum(amount) filter (where direction = 'income' and next_status in ('paid', 'settled')), 0),
    coalesce((select sum(paid_amount) from paid_expense_groups), 0)
  into v_actual_income, v_actual_expense
  from month_items;

  if v_actual_income < v_actual_expense then
    return jsonb_build_object(
      'ok', false,
      'message', format('当前收入不足，请补充赤字后结算。当前已收 %s，取整后已付支出 %s。', v_actual_income, v_actual_expense),
      'actual_income', v_actual_income,
      'actual_expense', v_actual_expense
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'message', '收入足以覆盖已付固定支出。',
    'actual_income', v_actual_income,
    'actual_expense', v_actual_expense
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_assign_accounting_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_scope text;
BEGIN
  IF TG_TABLE_NAME='home_external_transaction_requests' THEN
    IF NEW.external_source='aozora_school' THEN NEW.accounting_scope:='school'; END IF;
  ELSIF TG_TABLE_NAME='home_jpy_transactions' THEN
    IF NEW.external_source='aozora_school' OR coalesce(NEW.created_by_external,false) THEN NEW.accounting_scope:='school';
    ELSIF NEW.linked_fixed_month_item_id IS NOT NULL THEN
      SELECT i.accounting_scope INTO v_scope FROM public.home_fixed_month_items i WHERE i.id=NEW.linked_fixed_month_item_id AND i.user_id=NEW.user_id;
      NEW.accounting_scope:=coalesce(v_scope,NEW.accounting_scope,'household');
    ELSIF NEW.linked_cny_transaction_id IS NOT NULL THEN
      SELECT c.accounting_scope INTO v_scope FROM public.home_cny_transactions c WHERE c.id=NEW.linked_cny_transaction_id AND c.user_id=NEW.user_id;
      NEW.accounting_scope:=coalesce(v_scope,NEW.accounting_scope,'household');
    END IF;
  ELSIF TG_TABLE_NAME='home_cny_transactions' THEN
    IF NEW.external_source='aozora_school' OR coalesce(NEW.created_by_external,false) THEN NEW.accounting_scope:='school';
    ELSIF NEW.linked_fixed_month_item_id IS NOT NULL THEN
      SELECT i.accounting_scope INTO v_scope FROM public.home_fixed_month_items i WHERE i.id=NEW.linked_fixed_month_item_id AND i.user_id=NEW.user_id;
      NEW.accounting_scope:=coalesce(v_scope,NEW.accounting_scope,'household');
    ELSIF NEW.linked_jpy_transaction_id IS NOT NULL THEN
      SELECT j.accounting_scope INTO v_scope FROM public.home_jpy_transactions j WHERE j.id=NEW.linked_jpy_transaction_id AND j.user_id=NEW.user_id;
      NEW.accounting_scope:=coalesce(v_scope,NEW.accounting_scope,'household');
    END IF;
  ELSIF TG_TABLE_NAME='home_fixed_month_items' AND NEW.template_id IS NOT NULL THEN
    SELECT t.accounting_scope INTO v_scope FROM public.home_fixed_templates t WHERE t.id=NEW.template_id AND t.user_id=NEW.user_id;
    NEW.accounting_scope:=coalesce(v_scope,NEW.accounting_scope,'household');
  END IF;
  NEW.accounting_scope:=coalesce(NEW.accounting_scope,'household');
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.home_create_fixed_transfer(p_month_key text, p_currency text, p_transaction_type text, p_account_id uuid, p_transacted_at date, p_amount numeric DEFAULT NULL::numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_description text;
  v_direction text;
  v_payment_group text;
  v_jpy_transaction_id uuid := gen_random_uuid();
  v_fixed_item_id uuid := gen_random_uuid();
  v_status jsonb;
  v_amount numeric := 0;
begin
  if p_transaction_type not in ('fixed_in', 'fixed_out') then
    return jsonb_build_object('ok', false, 'message', '固定资金调拨类型无效。');
  end if;

  if not exists (
    select 1
    from home_accounts
    where id = p_account_id
      and user_id = auth.uid()
      and currency = p_currency
      and is_active
  ) then
    return jsonb_build_object('ok', false, 'message', '没有找到可使用的日元账户。');
  end if;

  if to_char(p_transacted_at, 'YYYY-MM') <> p_month_key then
    return jsonb_build_object('ok', false, 'message', '固定资金调拨日期必须在当前账期内。');
  end if;

  v_status := home_fixed_settlement_status(p_month_key, p_currency);
  v_amount := coalesce((v_status ->> 'transfer_amount')::numeric, 0);

  if p_transaction_type = 'fixed_out' and coalesce(v_status ->> 'state', '') <> 'deficit' then
    return jsonb_build_object('ok', false, 'message', '本月结算没有赤字，不需要补充。');
  end if;

  if p_transaction_type = 'fixed_in' and coalesce(v_status ->> 'state', '') <> 'surplus' then
    return jsonb_build_object('ok', false, 'message', '本月结算没有盈余，不能转入。');
  end if;

  if v_amount <= 0 then
    return jsonb_build_object('ok', false, 'message', '本月固定收支结算已平衡，不需要调拨。');
  end if;

  v_description := home_fixed_transfer_name(p_transaction_type);
  v_direction := home_fixed_transfer_direction(p_transaction_type);
  v_payment_group := case when p_transaction_type = 'fixed_in' then v_description else null end;

  if exists (
    select 1
    from home_fixed_month_items
    where user_id = auth.uid()
      and month_key = p_month_key
      and currency = p_currency
      and direction = v_direction
      and name = v_description
  ) then
    return jsonb_build_object('ok', false, 'message', format('本月已存在%s，请先删除后重新生成。', v_description));
  end if;

  insert into home_jpy_transactions (
    id,
    user_id,
    transaction_type,
    account_id,
    transfer_account_id,
    currency,
    transacted_at,
    amount,
    description,
    note,
    created_at
  )
  values (
    v_jpy_transaction_id,
    auth.uid(),
    p_transaction_type,
    p_account_id,
    null,
    p_currency,
    p_transacted_at,
    v_amount,
    v_description,
    coalesce(p_note, ''),
    now()
  );

  insert into home_fixed_month_items (
    id,
    user_id,
    template_id,
    month_key,
    currency,
    direction,
    name,
    amount,
    status,
    account_id,
    payment_group,
    due_date,
    term_no,
    total_terms,
    note,
    linked_jpy_transaction_id,
    created_at
  )
  values (
    v_fixed_item_id,
    auth.uid(),
    null,
    p_month_key,
    p_currency,
    v_direction,
    v_description,
    v_amount,
    'paid',
    p_account_id,
    v_payment_group,
    p_transacted_at,
    null,
    null,
    coalesce(p_note, ''),
    v_jpy_transaction_id,
    now()
  );

  update home_jpy_transactions
  set linked_fixed_month_item_id = v_fixed_item_id
  where id = v_jpy_transaction_id
    and user_id = auth.uid();

  return jsonb_build_object(
    'ok', true,
    'message', format('%s已生成，金额 %s。', v_description, v_amount),
    'amount', v_amount,
    'fixed_item_id', v_fixed_item_id,
    'jpy_transaction_id', v_jpy_transaction_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_reset_plain_fixed_expenses_if_deficit(p_month_key text, p_currency text DEFAULT 'JPY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_check jsonb;
  v_updated_count integer := 0;
begin
  v_check := public.home_check_fixed_paid_balance(p_month_key, p_currency);

  if coalesce((v_check ->> 'ok')::boolean, false) then
    return jsonb_build_object(
      'reset_expense_status', false,
      'reset_count', 0,
      'message', '删除后固定收支仍满足已付结算条件。'
    );
  end if;

  update public.home_fixed_month_items i
  set status = 'unpaid'
  where i.user_id = auth.uid()
    and i.month_key = p_month_key
    and i.currency = p_currency
    and i.direction = 'expense'
    and i.linked_jpy_transaction_id is null
    and i.status <> 'unpaid'
    -- Phase 3F：School 投影项不参与赤字重置
    and not public.home_fixed_item_has_external_projection(i.id)
    and not exists (
      select 1
      from public.home_fixed_advance_payments ap
      where ap.user_id = auth.uid()
        and ap.month_key = i.month_key
        and ap.currency = i.currency
        and ap.payment_group = coalesce(i.payment_group, '未分组')
    );

  get diagnostics v_updated_count = row_count;

  return jsonb_build_object(
    'reset_expense_status', true,
    'reset_count', v_updated_count,
    'message', '删除后固定收支重新出现赤字，未进入垫付流程的普通固定支出已改回未付。'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_guard_projection_linked_fixed_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if exists (select 1 from public.home_external_fixed_payment_projections p where p.fixed_month_item_id=old.id) then
    if tg_op='DELETE' then
      raise exception using errcode='42501',message='HOME_PROJECTION_FIXED_ITEM_DELETE_FORBIDDEN';
    end if;
    -- Phase 3F：仅 home_confirm_projection_fixed_item_status 可改 status
    if current_setting('home.phase3f_projection_status_write',true) is distinct from 'on'
       or (to_jsonb(new)-'status') is distinct from (to_jsonb(old)-'status') then
      raise exception using errcode='42501',message='HOME_PROJECTION_FIXED_ITEM_UPDATE_FORBIDDEN';
    end if;
  end if;
  if exists (select 1 from public.home_card_statement_cycles c where c.household_remainder_fixed_item_id=old.id) then
    if tg_op='DELETE' then
      raise exception using errcode='42501',message='HOME_CARD_STATEMENT_ITEM_DELETE_FORBIDDEN';
    end if;
    if current_setting('home.phase3e_statement_item_write',true) is distinct from 'on'
       or (to_jsonb(new)-'amount') is distinct from (to_jsonb(old)-'amount') then
      raise exception using errcode='42501',message='HOME_CARD_STATEMENT_ITEM_UPDATE_FORBIDDEN';
    end if;
  end if;
  return case when tg_op='DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.home_create_fixed_advance_payment(p_month_key text, p_currency text, p_payment_group text, p_account_id uuid, p_transacted_at date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_group text:=coalesce(nullif(trim(p_payment_group),''),'未分组'); v_amount numeric:=0;
  v_transaction_id uuid:=gen_random_uuid(); v_advance_id uuid:=gen_random_uuid(); v_item_count integer:=0;
begin
  if p_currency<>'JPY' then return jsonb_build_object('ok',false,'message','固定垫付目前只支持日元。'); end if;
  if to_char(p_transacted_at,'YYYY-MM')<>p_month_key then return jsonb_build_object('ok',false,'message','垫付日期必须在当前账期内。'); end if;
  if not exists(select 1 from public.home_accounts where id=p_account_id and user_id=auth.uid() and currency=p_currency and is_active) then return jsonb_build_object('ok',false,'message','没有找到可使用的日元垫付账户。'); end if;
  if public.home_fixed_advance_group_has_card_statement(p_month_key,p_currency,v_group) then
    return jsonb_build_object('ok',false,'code','HOME_CARD_STATEMENT_GROUP_ADVANCE_FORBIDDEN','message','该支付分组包含信用卡statement关联固定项，Phase 3F前不能垫付。');
  end if;
  if public.home_fixed_scope_has_external_projection(p_month_key,p_currency,'expense',v_group) then
    return jsonb_build_object('ok',false,'code','HOME_PROJECTION_FIXED_ITEM_ADVANCE_FORBIDDEN','message','该支付分组包含School信用卡projection固定项，Phase 3F前不能垫付。');
  end if;
  if exists(select 1 from public.home_fixed_advance_payments where user_id=auth.uid() and month_key=p_month_key and currency=p_currency and payment_group=v_group) then return jsonb_build_object('ok',false,'message','本账期该支付分组已经生成过垫付记录。'); end if;
  select count(*),public.home_round_up_1000(coalesce(sum(amount),0)) into v_item_count,v_amount from public.home_fixed_month_items where user_id=auth.uid() and month_key=p_month_key and currency=p_currency and direction='expense' and linked_jpy_transaction_id is null and coalesce(payment_group,'未分组')=v_group;
  if v_item_count<=0 or v_amount<=0 then return jsonb_build_object('ok',false,'message','该支付分组没有可垫付的固定支出。'); end if;
  insert into public.home_jpy_transactions(id,user_id,transaction_type,account_id,transfer_account_id,currency,transacted_at,amount,description,note,created_at)
  values(v_transaction_id,auth.uid(),'fixed_advance_out',p_account_id,null,p_currency,p_transacted_at,v_amount,format('%s 固定支出垫付',v_group),coalesce(p_note,''),now());
  insert into public.home_fixed_advance_payments(id,user_id,month_key,currency,payment_group,account_id,amount,status,paid_at,out_transaction_id,note,created_at)
  values(v_advance_id,auth.uid(),p_month_key,p_currency,v_group,p_account_id,v_amount,'pending',p_transacted_at,v_transaction_id,coalesce(p_note,''),now());
  update public.home_fixed_month_items set status='paid' where user_id=auth.uid() and month_key=p_month_key and currency=p_currency and direction='expense' and linked_jpy_transaction_id is null and coalesce(payment_group,'未分组')=v_group;
  return jsonb_build_object('ok',true,'message',format('%s 固定支出已垫付，金额 %s。',v_group,v_amount),'advance_id',v_advance_id,'jpy_transaction_id',v_transaction_id,'amount',v_amount,'item_count',v_item_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.home_update_fixed_month_item_status(p_item_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_item public.home_fixed_month_items%rowtype; v_check jsonb;
begin
  if p_status not in ('unpaid','paid','settled') then return jsonb_build_object('ok',false,'message','固定项状态无效。'); end if;
  select * into v_item from public.home_fixed_month_items where id=p_item_id and user_id=auth.uid();
  if not found then return jsonb_build_object('ok',false,'message','没有找到可更新的固定项。'); end if;
  if public.home_fixed_item_has_external_projection(v_item.id) then return jsonb_build_object('ok',false,'code','HOME_PROJECTION_FIXED_ITEM_STATUS_FORBIDDEN','message','School信用卡projection固定项不能使用普通状态writer。'); end if;
  if public.home_fixed_item_has_card_statement(v_item.id) then return jsonb_build_object('ok',false,'code','HOME_CARD_STATEMENT_ITEM_STATUS_FORBIDDEN','message','信用卡statement关联固定项不能使用普通状态writer。'); end if;
  if v_item.linked_jpy_transaction_id is not null then return jsonb_build_object('ok',false,'message','调拨记录状态固定为已付。'); end if;
  if v_item.direction='expense' and exists(select 1 from public.home_fixed_advance_payments ap where ap.user_id=auth.uid() and ap.month_key=v_item.month_key and ap.currency=v_item.currency and ap.payment_group=coalesce(v_item.payment_group,'未分组')) then return jsonb_build_object('ok',false,'message','该固定支出分组已进入垫付流程，状态不能单独修改。'); end if;
  if v_item.direction='expense' and p_status in ('paid','settled') then v_check:=public.home_check_fixed_paid_balance(v_item.month_key,v_item.currency,p_item_id,p_status); if not coalesce((v_check->>'ok')::boolean,false) then return v_check; end if; end if;
  update public.home_fixed_month_items set status=p_status where id=p_item_id and user_id=auth.uid() and linked_jpy_transaction_id is null;
  return jsonb_build_object('ok',true,'message','固定项状态已更新。','updated_count',1);
end;
$function$

CREATE OR REPLACE FUNCTION public.home_update_fixed_month_items_status(p_month_key text, p_currency text, p_direction text, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_updated_count integer:=0; v_skipped integer:=0; v_check jsonb;
begin
  if p_direction not in ('income','expense') then return jsonb_build_object('ok',false,'message','固定项收支方向无效。'); end if;
  if p_status not in ('unpaid','paid','settled') then return jsonb_build_object('ok',false,'message','固定项状态无效。'); end if;
  -- ① 原来这里是整批拒绝。改为跳过：projection 项由前端随后单独走
  --    home_confirm_projection_fixed_item_status，那是它们唯一合法的入口。
  if public.home_fixed_scope_has_card_statement(p_month_key,p_currency,p_direction) then return jsonb_build_object('ok',false,'code','HOME_CARD_STATEMENT_ITEM_BULK_STATUS_FORBIDDEN','message','范围内包含信用卡statement关联固定项，不能使用批量状态writer。'); end if;
  if p_direction='expense' and p_status in ('paid','settled') then v_check:=public.home_check_fixed_paid_balance(p_month_key,p_currency,null,null,p_direction,p_status); if not coalesce((v_check->>'ok')::boolean,false) then return v_check; end if; end if;
  -- ③ 先数清楚这次会跳过几条，返回里报出去，前端据此决定要不要补那一步
  select count(*) into v_skipped
  from public.home_fixed_month_items i
  where i.user_id=auth.uid() and i.month_key=p_month_key and i.currency=p_currency
    and i.direction=p_direction
    and public.home_fixed_item_has_external_projection(i.id);
  -- ② 排除 projection 项
  update public.home_fixed_month_items i set status=p_status where i.user_id=auth.uid() and i.month_key=p_month_key and i.currency=p_currency and i.direction=p_direction and i.linked_jpy_transaction_id is null and not public.home_fixed_item_has_external_projection(i.id) and not(p_direction='expense' and exists(select 1 from public.home_fixed_advance_payments ap where ap.user_id=auth.uid() and ap.month_key=i.month_key and ap.currency=i.currency and ap.payment_group=coalesce(i.payment_group,'未分组')));
  get diagnostics v_updated_count=row_count;
  return jsonb_build_object('ok',true,'message','固定项状态已批量更新。','updated_count',v_updated_count,'skipped_projection_count',v_skipped);
end;
$function$

CREATE OR REPLACE FUNCTION public.home_delete_fixed_month_item(p_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor_id uuid := auth.uid();
begin
  if v_actor_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_DELETE_UNAUTHENTICATED',
      'message', '请先登录后再删除固定项。'
    );
  end if;

  return public.home_delete_fixed_month_item_core(p_item_id, v_actor_id, 'JPY');
end;
$function$

CREATE OR REPLACE FUNCTION public.home_confirm_projection_fixed_item_status(p_item_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_item public.home_fixed_month_items%rowtype;
begin
  if p_status not in ('unpaid','paid','settled') then
    return jsonb_build_object('ok',false,'message','固定项状态无效。');
  end if;

  select * into v_item
  from public.home_fixed_month_items
  where id=p_item_id and user_id=auth.uid();

  if not found then
    return jsonb_build_object('ok',false,'message','没有找到可更新的固定项。');
  end if;

  if not public.home_fixed_item_has_external_projection(v_item.id) then
    return jsonb_build_object(
      'ok',false,
      'code','HOME_NOT_PROJECTION_FIXED_ITEM',
      'message','该固定项不是School投影项，请使用普通状态writer。');
  end if;

  if public.home_fixed_item_has_card_statement(v_item.id) then
    return jsonb_build_object(
      'ok',false,
      'code','HOME_CARD_STATEMENT_ITEM_STATUS_FORBIDDEN',
      'message','信用卡statement关联固定项不能使用本writer。');
  end if;

  if v_item.linked_jpy_transaction_id is not null then
    return jsonb_build_object('ok',false,'message','调拨记录状态固定为已付。');
  end if;

  if v_item.status = p_status then
    return jsonb_build_object('ok',true,'message','状态未变化。','updated_count',0);
  end if;

  perform set_config('home.phase3f_projection_status_write','on',true);

  update public.home_fixed_month_items
  set status=p_status
  where id=v_item.id and user_id=auth.uid();

  perform set_config('home.phase3f_projection_status_write','off',true);

  return jsonb_build_object(
    'ok',true,
    'message','School投影固定项状态已更新。',
    'updated_count',1,
    'item_id',v_item.id,
    'status',p_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.home_delete_fixed_month_item_core(p_item_id uuid, p_actor_id uuid, p_expected_currency text DEFAULT NULL::text, p_pair_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_item public.home_fixed_month_items%rowtype;
  v_check jsonb;
  v_deleted_count integer := 0;
  v_expected_currency text := nullif(upper(btrim(coalesce(p_expected_currency, ''))), '');
  v_authorization_id uuid := gen_random_uuid();
  v_core_nonce uuid := gen_random_uuid();
  v_transaction_id xid8;
begin
  if p_actor_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_DELETE_UNAUTHENTICATED',
      'message', '请先登录后再删除固定项。'
    );
  end if;

  if p_item_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_ALREADY_ABSENT',
      'message', '该固定项已不存在，请刷新页面。'
    );
  end if;

  select * into v_item
  from public.home_fixed_month_items i
  where i.id = p_item_id
    and i.user_id = p_actor_id
    and (v_expected_currency is null or i.currency = v_expected_currency)
  for update;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_ALREADY_ABSENT',
      'message', '该固定项已不存在，请刷新页面。'
    );
  end if;

  v_check := public.home_check_fixed_month_item_delete_eligibility(
    v_item, p_actor_id, p_pair_transaction_id);
  if not coalesce((v_check ->> 'ok')::boolean, false) then
    return v_check;
  end if;

  v_transaction_id := pg_current_xact_id();

  insert into public.home_fixed_month_item_delete_authorizations(
    authorization_id,
    transaction_id,
    fixed_month_item_id,
    actor_id,
    operation_type,
    currency,
    core_nonce,
    pair_transaction_id
  ) values (
    v_authorization_id,
    v_transaction_id,
    v_item.id,
    p_actor_id,
    'delete',
    v_item.currency,
    v_core_nonce,
    p_pair_transaction_id
  );

  delete from public.home_fixed_month_items i
  where i.id = v_item.id
    and i.user_id = p_actor_id;
  get diagnostics v_deleted_count = row_count;

  if v_deleted_count <> 1 then
    raise exception using
      errcode = '55000',
      message = 'HOME_FIXED_ITEM_DELETE_INTERNAL_CONTRACT_ERROR';
  end if;

  if exists (
    select 1
    from public.home_fixed_month_item_delete_authorizations a
    where a.authorization_id = v_authorization_id
  ) then
    raise exception using
      errcode = '55000',
      message = 'HOME_FIXED_ITEM_DELETE_AUTHORIZATION_NOT_CONSUMED';
  end if;

  return jsonb_build_object(
    'ok', true,
    'code', 'HOME_FIXED_ITEM_DELETED',
    'deleted_count', 1,
    'item_id', v_item.id,
    'currency', v_item.currency,
    'message', case
      when v_item.currency = 'CNY' then '人民币固定项已删除。'
      else '固定项已删除。'
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_delete_jpy_transaction(p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_transaction public.home_jpy_transactions%rowtype;
  v_linked_fixed_month_item_id uuid;
  v_item public.home_fixed_month_items%rowtype;
  v_reset jsonb := jsonb_build_object('reset_expense_status', false);
  v_linked_deleted boolean := false;
  v_message text := '已删除。';
  v_core jsonb;
begin
  select *
  into v_transaction
  from public.home_jpy_transactions
  where id = p_transaction_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'message', '没有找到可删除的日元流水。');
  end if;

  if v_transaction.created_by_external is true
     or nullif(btrim(v_transaction.external_source), '') is not null
     or v_transaction.external_source_id is not null
     or nullif(btrim(v_transaction.external_event_type), '') is not null
     or nullif(btrim(v_transaction.external_idempotency_key), '') is not null
     or nullif(btrim(v_transaction.external_reference_type), '') is not null
     or v_transaction.external_reference_id is not null
     or nullif(btrim(v_transaction.external_note), '') is not null
     or nullif(btrim(v_transaction.external_payload_hash), '') is not null
     or v_transaction.external_created_at is not null then
    return jsonb_build_object(
      'ok', false, 'code', 'EXTERNAL_TRANSACTION_IMMUTABLE',
      'message', 'EXTERNAL_TRANSACTION_IMMUTABLE'
    );
  end if;

  if v_transaction.user_id is distinct from auth.uid() then
    return jsonb_build_object('ok', false, 'message', '没有找到可删除的日元流水。');
  end if;

  if v_transaction.transaction_type in ('fixed_advance_out', 'fixed_advance_in') then
    return jsonb_build_object('ok', false, 'message', '固定垫付流水由固定收支流程控制，不能在零散收支中删除。');
  end if;

  v_linked_fixed_month_item_id := public.home_resolve_fixed_transfer_item_id(v_transaction);

  if v_linked_fixed_month_item_id is not null then
    select *
    into v_item
    from public.home_fixed_month_items
    where id = v_linked_fixed_month_item_id
      and user_id = auth.uid();

    if not found then
      return jsonb_build_object('ok', false, 'message', '调拨流水链接的固定项不存在，请检查旧数据后再删除。');
    end if;

    -- 2026-09-01 Step D：经窄 DEFINER 入口删除配对固定项。
    -- 本函数是 INVOKER，无权直接调 postgres-only 的 core；窄入口内部从
    -- auth.uid() 取 actor 并校验配对关系，再转调 core。
    v_core := public.home_delete_fixed_transfer_pair_item(
      v_linked_fixed_month_item_id,
      v_transaction.id
    );

    -- 失败原样上抛。projection / statement / correction / funded / 垫付等
    -- 保护命中时必须让整个删除失败；同一事务内 return 会连带回滚，
    -- 流水不会被误删。
    if not coalesce((v_core ->> 'ok')::boolean, false) then
      return v_core;
    end if;

    v_linked_deleted := true;
  elsif v_transaction.transaction_type in ('fixed_in', 'fixed_out') then
    v_message := '已删除日元流水，但旧数据链接不完整，未能唯一匹配固定项。';
  end if;

  delete from public.home_jpy_transactions
  where id = v_transaction.id
    and user_id = auth.uid();

  if v_linked_deleted then
    v_reset := public.home_reset_plain_fixed_expenses_if_deficit(v_item.month_key, v_item.currency);
  end if;

  return jsonb_build_object(
    'ok', true,
    'deleted_count', 1,
    'linked_deleted', v_linked_deleted,
    'reset_expense_status', coalesce((v_reset ->> 'reset_expense_status')::boolean, false),
    'message', case
      when v_linked_deleted and coalesce((v_reset ->> 'reset_expense_status')::boolean, false)
        then '已同步删除固定收支记录；删除后重新出现赤字，普通固定支出已改回未付。'
      when v_linked_deleted
        then '已同步删除固定收支记录。'
      else v_message
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_check_fixed_month_item_delete_eligibility(p_item home_fixed_month_items, p_actor_id uuid, p_pair_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_actor_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_DELETE_UNAUTHENTICATED',
      'message', '请先登录后再删除固定项。'
    );
  end if;

  if p_item.id is null or p_item.user_id is distinct from p_actor_id then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_ALREADY_ABSENT',
      'message', '该固定项已不存在，请刷新页面。'
    );
  end if;

  -- 配对删除场景跳过状态检查：固定调拨项由 home_create_fixed_transfer 创建，
  -- 状态写死 paid，永远无法满足「仅 unpaid」。
  if p_pair_transaction_id is null and p_item.status is distinct from 'unpaid' then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_DELETE_STATUS_FORBIDDEN',
      'message', '仅未支付的普通固定项可以删除。已支付或已结算项目请先撤销支付或使用纠正流程。'
    );
  end if;

  if exists (
    select 1
    from public.home_external_fixed_payment_projections p
    where p.fixed_month_item_id = p_item.id
      and (
        p.projection_status = 'corrected'
        or p.supersedes_projection_id is not null
        or exists (
          select 1
          from public.home_external_fixed_payment_projections replacement
          where replacement.supersedes_projection_id = p.id
        )
      )
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_CORRECTION_FIXED_ITEM_DELETE_FORBIDDEN',
      'message', '该固定项属于纠正或replacement链路，不能直接删除。'
    );
  end if;

  if exists (
    select 1
    from public.home_external_fixed_payment_projections p
    where p.fixed_month_item_id = p_item.id
      and (
        p.funding_status is distinct from 'unfunded'
        or p.funding_account_id is not null
        or p.funding_transaction_id is not null
        or p.funded_at is not null
      )
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FUNDED_FIXED_ITEM_DELETE_FORBIDDEN',
      'message', '该固定项已经进入资金处理流程，不能直接删除。'
    );
  end if;

  if exists (
    select 1
    from public.home_external_fixed_payment_projections p
    where p.fixed_month_item_id = p_item.id
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_PROJECTION_FIXED_ITEM_DELETE_FORBIDDEN',
      'message', '该固定项来自外部固定支付链路，不能直接删除。'
    );
  end if;

  if exists (
    select 1
    from public.home_card_statement_cycles c
    where c.household_remainder_fixed_item_id = p_item.id
  ) or exists (
    select 1
    from public.home_card_statement_cycle_revisions r
    where r.household_remainder_fixed_item_id = p_item.id
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_STATEMENT_FIXED_ITEM_DELETE_FORBIDDEN',
      'message', '该固定项已经进入账单处理流程，不能直接删除。'
    );
  end if;

  if p_item.direction = 'expense' and exists (
    select 1
    from public.home_fixed_advance_payments a
    where a.user_id = p_item.user_id
      and a.month_key = p_item.month_key
      and a.currency = p_item.currency
      and a.payment_group = coalesce(p_item.payment_group, '未分组')
  ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_ADVANCE_FIXED_ITEM_DELETE_FORBIDDEN',
      'message', '该固定项所在支付分组已经进入垫付流程，不能直接删除。'
    );
  end if;

  -- 关联流水检查。
  -- 普通场景（p_pair_transaction_id 为 NULL）：任何关联即拒绝，与基线一致。
  -- 配对场景：仅放行所传的那一笔 JPY 流水，其余关联一律拒绝——不能笼统豁免，
  -- 否则固定项关联流水 X 时删流水 Y 会误删。
  if (
       p_item.linked_jpy_transaction_id is not null
       and (p_pair_transaction_id is null
            or p_item.linked_jpy_transaction_id is distinct from p_pair_transaction_id)
     )
     or p_item.linked_cny_transaction_id is not null
     or exists (
       select 1
       from public.home_jpy_transactions t
       where t.linked_fixed_month_item_id = p_item.id
         and (p_pair_transaction_id is null
              or t.id is distinct from p_pair_transaction_id)
     )
     or exists (
       select 1
       from public.home_cny_transactions t
       where t.linked_fixed_month_item_id = p_item.id
     ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_LINKED_PAYMENT_FIXED_ITEM_DELETE_FORBIDDEN',
      'message', '该固定项已经关联Cash流水，不能直接删除。'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'code', 'HOME_FIXED_ITEM_DELETE_ELIGIBLE'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_delete_fixed_transfer_pair_item(p_item_id uuid, p_pair_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_item public.home_fixed_month_items%rowtype;
  v_txn public.home_jpy_transactions%rowtype;
begin
  if v_actor is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_ITEM_DELETE_UNAUTHENTICATED',
      'message', '请先登录后再删除固定项。'
    );
  end if;

  if p_item_id is null or p_pair_transaction_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_TRANSFER_PAIR_INVALID',
      'message', '配对删除需要同时指定固定项与流水。'
    );
  end if;

  -- 流水：必须属于本人，且是固定资金调拨
  select * into v_txn
  from public.home_jpy_transactions
  where id = p_pair_transaction_id
    and user_id = v_actor;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_TRANSFER_PAIR_INVALID',
      'message', '配对流水不存在或不属于当前用户。'
    );
  end if;

  if v_txn.transaction_type not in ('fixed_in', 'fixed_out') then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_TRANSFER_PAIR_INVALID',
      'message', '配对流水不是固定资金调拨，不能使用本入口。'
    );
  end if;

  -- 固定项：必须属于本人
  select * into v_item
  from public.home_fixed_month_items
  where id = p_item_id
    and user_id = v_actor;

  if not found then
    -- 用 PAIR_INVALID 而非 ALREADY_ABSENT：本入口的语义是「校验配对关系」，
    -- 而 user_id = auth.uid() 是查询条件的一部分。项不存在与项属于他人在
    -- 这里不作区分，也不应区分——区分会泄露「该 id 确实存在但不属于你」。
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_TRANSFER_PAIR_INVALID',
      'message', '配对固定项不存在或不属于当前用户。'
    );
  end if;

  -- 必须构成真实配对：两个方向都成立。
  -- 生产核查确认 5 组配对全部双向完整，无单向情形，故用 AND。
  -- 详见文件头设计说明三。
  if not (
       v_item.linked_jpy_transaction_id is not distinct from v_txn.id
       and v_txn.linked_fixed_month_item_id is not distinct from v_item.id
     ) then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_TRANSFER_PAIR_INVALID',
      'message', '该固定项与所传流水不构成配对关系。'
    );
  end if;

  if v_item.currency is distinct from v_txn.currency then
    return jsonb_build_object(
      'ok', false,
      'code', 'HOME_FIXED_TRANSFER_PAIR_INVALID',
      'message', '配对双方币种不一致。'
    );
  end if;

  -- 其余七条检查全部交给 core，本入口不做任何豁免
  return public.home_delete_fixed_month_item_core(
    v_item.id,
    v_actor,
    v_item.currency,
    v_txn.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.home_resolve_fixed_transfer_item_id(p_transaction home_jpy_transactions)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_direction text;
  v_name text;
  v_month_key text;
  v_candidate_id uuid;
  v_candidate_count integer;
begin
  if p_transaction.linked_fixed_month_item_id is not null then
    return p_transaction.linked_fixed_month_item_id;
  end if;

  v_direction := home_fixed_transfer_direction(p_transaction.transaction_type);
  v_name := home_fixed_transfer_name(p_transaction.transaction_type);
  v_month_key := to_char(p_transaction.transacted_at, 'YYYY-MM');

  if v_direction is null or v_name is null then
    return null;
  end if;

  select count(*), (array_agg(i.id))[1]
  into v_candidate_count, v_candidate_id
  from home_fixed_month_items i
  where i.user_id = auth.uid()
    and i.currency = p_transaction.currency
    and i.month_key = v_month_key
    and i.direction = v_direction
    and i.name = v_name
    and i.amount = p_transaction.amount
    and i.linked_jpy_transaction_id is null
    and (i.account_id is null or i.account_id = p_transaction.account_id);

  if v_candidate_count = 1 then
    update home_fixed_month_items
    set linked_jpy_transaction_id = p_transaction.id
    where id = v_candidate_id
      and user_id = auth.uid();

    update home_jpy_transactions
    set linked_fixed_month_item_id = v_candidate_id
    where id = p_transaction.id
      and user_id = auth.uid();

    return v_candidate_id;
  end if;

  return null;
end;
$function$

